        tuple(sorted(minutes)),
        tuple(sorted(hours)),
        frozenset(months),
        frozenset(dom),
        dom_last,
        dom_unrestricted,
        frozenset(dow),
        frozenset(dow_last),
        tuple(dow_nth),
        dow_unrestricted,
